(window.VADE_TASKS=window.VADE_TASKS||{})["FIN2-033"]={"id": "FIN2-033", "number": 33, "domain": "finance", "released": true, "group": "Passenger Airlines", "category": "Disclosure Analysis", "title": "Delta: allocating co-brand revenue obligations", "question": "Delta Air Lines' FY2025 Form 10-K explains that consideration under its American Express co-brand agreements is allocated by relative selling price to several performance obligations, part of which flows into the SkyMiles loyalty program deferred revenue pool. Using only that 10-K as available through July 10, 2026 (no later earnings calls, 2026 guidance or third-party estimates), assess whether the filing supports the claim that Delta's American Express consideration is building up in deferred revenue faster than it is being recognized and that this build will reverse in the near term.\n\nTo support your judgment, establish which disclosed FY2025 consideration measure is the defensible starting population for the allocation and why; where each allocated performance obligation is recognized in Delta's revenue lines, saying where the 10-K does not disclose a receiving line or timing and labelling any placement you infer as an inference, and whether the American Express-sourced portion of each receiving line is identifiable, only boundable (give any bound), or not identifiable; whether the loyalty program deferred revenue balance reconciles across the balance sheet, the Note 2 rollforward and the cash-flow statement; the direction of the gap between deferral and recognition and the population level at which that direction holds; and how the current/noncurrent split changed and what it implies for the near term.\n\nConventions: measure each year's pool change for 2023, 2024 and 2025 as the Note 2 rollforward ending balance minus its beginning balance (positive = net deferral build) and compare it with the same year's cash-flow operating adjustment for loyalty program deferred revenue, stating any difference in USD millions; define the pool on the balance sheet as current plus noncurrent loyalty program deferred revenue at December 31, 2024 and December 31, 2025, and the current share as current divided by that sum; for the near-term test, compare the December 31, 2025 current portion with FY2025 total revenue recognized out of the pool (travel plus non-travel miles redeemed); treat any amount you derive for a revenue line as an upper bound and say what it still contains, not as an estimate of the American Express portion. Report dollar amounts in USD millions (or in billions where the 10-K gives only billions) and percentages to one decimal place.", "cutoff": "2026-07-10", "core_conclusion": "In Delta's FY2025 10-K, the relative-selling-price allocation applies to total cash sales from marketing agreements ($8.0 billion, substantially all American Express), not to the $8.2 billion of remuneration from American Express. Of the allocated obligations only the brand/remaining-obligations line can be bounded (about $3,143M ceiling within loyalty program revenue); award travel, baggage fee waivers and lounge access cannot be isolated in their receiving lines, and priority boarding's receiving line and timing are not separately disclosed (travel-related services only as a labelled inference) with no identifiable American Express amount. The SkyMiles deferred pool ties exactly across the balance sheet and Note 2 (9,262 and 8,826) and the cash-flow adjustment matches the rollforward within $1M for 2023-2025, showing a net deferral build each year (436, 406, 538). The current portion rose $562M to 52.6% of the pool and exceeds FY2025 pool recognition (4,456), indicating higher near-term recognition, but a net reversal is not determinable without 2026 miles earned, and the direction holds only at pool level, not for American Express specifically.", "atoms": [{"label": "Defensible starting consideration population for mapping the Amex relative-selling-price allocation, chosen between (a) the dollar remuneration from American Express and (b) the cash-sales total from all loyalty marketing agreements, with both FY2025 reported dollar amounts and the reason the other measure is not the allocation base", "expected": "Total cash sales from marketing agreements ($8.0 billion in FY2025; substantially all American Express) is the population the 10-K allocates to travel and other performance obligations by relative selling price. Remuneration from American Express ($8.2 billion in 2025) is a differently defined measure that the 10-K does not reconcile (gap about $0.2 billion on rounded inputs), so it cannot be dropped into the allocation. The Q2 2026 call's $9 billion is 2026 guidance, not FY2025 data.", "unit": null, "tolerance": null, "fatal": true, "scored": true, "evidence": [1, 2, 3, 4, 6, 22, 23]}, {"label": "For each allocated performance obligation (award travel; baggage fee waivers and other services performed in conjunction with a passenger's flight; lounge access; brand use and other remaining obligations; and priority boarding, whose receiving line is not separately disclosed): the receiving revenue line and recognition timing where disclosed, and whether the American Express-sourced portion of that line is identified, bounded, or not identifiable, with any computed bound", "expected": "Award travel -> loyalty program deferred revenue, then loyalty travel awards (passenger revenue) as miles are redeemed and transportation is provided: not identifiable (one homogeneous pool; FY2025 line $4,237M equals travel miles redeemed). Baggage fee waivers and other services performed in conjunction with a passenger's flight -> travel-related services (passenger revenue) when performed: not identifiable (line $2,043M, no American Express split disclosed). Lounge access -> miscellaneous (other revenue) as access is provided: not identifiable (line $1,320M also holds travel products, codeshare agreements and international joint venture settlements). Brand value and other remaining obligations -> loyalty program (other revenue) as miles are delivered: bounded above at about $3,143M (3,362 - 219 non-travel miles redeemed), a ceiling that still includes other marketing-agreement partners. Priority boarding is an allocated obligation (and a selling-price input) but its receiving line and recognition timing are not separately disclosed; travel-related services placement is acceptable only if labelled an inference, and its American Express-sourced amount is not identifiable. Not assigning priority boarding to a line is not an error. No relative-selling-price percentages are disclosed.", "unit": "USD millions", "tolerance": 2, "fatal": true, "scored": true, "evidence": [5, 6, 7, 8, 9, 10, 11, 13, 15, 16, 17, 18]}, {"label": "Whether balance-sheet current plus noncurrent loyalty program deferred revenue equals the Note 2 rollforward ending balance at December 31, 2025 and at December 31, 2024 (tie or no tie), with the summed amount at each date", "expected": "Ties exactly: 4,876 + 4,386 = 9,262 at December 31, 2025 and 4,314 + 4,512 = 8,826 at December 31, 2024 ($ millions), matching the Note 2 rollforward balances and the CAE's rounded $9.3 billion.", "unit": "USD millions", "tolerance": null, "fatal": true, "scored": true, "evidence": [13, 19, 21]}, {"label": "Whether the cash-flow operating adjustment for loyalty program deferred revenue matches the Note 2 rollforward net change for each of 2025, 2024 and 2023, giving each year's rollforward net change, cash-flow amount and difference", "expected": "Matches within rounding: 2025 rollforward net change 436 vs cash flow 435 (difference 1); 2024 406 vs 407 (difference 1); 2023 538 vs 538 (difference 0), $ millions.", "unit": "USD millions", "tolerance": 1, "fatal": true, "scored": true, "evidence": [13, 20]}, {"label": "Direction of the pool-level gap between miles deferred and revenue recognized out of the SkyMiles pool in each of 2025, 2024 and 2023 (recognized revenue lagging or leading the deferrals), with each year's net change", "expected": "In all three years miles earned exceeded travel plus non-travel redemptions, so revenue recognized out of the SkyMiles pool lagged the pool's deferrals: net builds of about $436M (2025), $406M (2024) and $538M (2023), with cash-flow adjustments of +435, +407 and +538.", "unit": "USD millions", "tolerance": 1, "fatal": true, "scored": true, "evidence": [13, 20]}, {"label": "Year-over-year change in the current and in the noncurrent loyalty program deferred revenue balances from December 31, 2024 to December 31, 2025, and the current share of the total pool at each date", "expected": "Current +$562M (4,314 to 4,876); noncurrent -$126M (4,512 to 4,386); current share about 48.9% at December 31, 2024 and about 52.6% at December 31, 2025.", "unit": "USD millions", "tolerance": 1, "fatal": true, "scored": true, "evidence": [13, 14, 19]}, {"label": "Whether the 10-K supports an expected near-term net reversal of the FY2025 pooled deferral build, comparing the December 31, 2025 current portion with FY2025 total pool recognition (travel plus non-travel redemptions), and which disclosed or undisclosed inputs determine that answer", "expected": "Higher near-term recognition is indicated: the $4,876M current portion (the estimate of revenue expected to be recognized in the next twelve months based on projected redemptions) exceeds FY2025 pool recognition of $4,456M (4,237 + 219) by about $420M. A net reversal of the pool is not determinable because 2026 miles earned are not disclosed in the 10-K; the call's $9 billion remuneration guidance is not a deferral figure.", "unit": "USD millions", "tolerance": 1, "fatal": true, "scored": true, "evidence": [13, 14, 19, 22]}, {"label": "Whether the pooled deferral direction can be attributed specifically to American Express consideration, and the disclosure feature that governs this", "expected": "Not attributable to American Express: miles are combined in one homogeneous pool and are not separately identifiable, and the rollforward's miles earned include miles earned through travel and miles sold to participating companies (substantially all, not all, of marketing-agreement cash sales are American Express), so the direction holds only for the pooled mix.", "unit": null, "tolerance": null, "fatal": true, "scored": true, "evidence": [4, 11, 12]}], "requirements": [{"atom": "Direction of the pool-level gap between miles deferred and revenue recognized out of the SkyMiles pool in each of 2025, 2024 and 2023 (recognized revenue lagging or leading the deferrals), with each year's net change", "criterion": "States that, at the pooled SkyMiles level, recognition lagged deferral (net deferral build) in each of 2025, 2024 and 2023, with rollforward net changes of about +436, +406 and +538 USD millions (±1) measured as ending minus beginning balance, consistent with cash-flow adjustments of +435, +407 and +538.", "fatal": true}, {"atom": "Whether the pooled deferral direction can be attributed specifically to American Express consideration, and the disclosure feature that governs this", "criterion": "Concludes that the deferral-build direction holds only for the pooled mix and cannot be attributed specifically to American Express consideration. The reason must be that miles sit in one homogeneous pool that is not separately identifiable, and that miles earned include travel-earned miles and miles sold to all participating companies (marketing-agreement cash sales are substantially all, not all, American Express).", "fatal": true}, {"atom": "Whether the 10-K supports an expected near-term net reversal of the FY2025 pooled deferral build, comparing the December 31, 2025 current portion with FY2025 total pool recognition (travel plus non-travel redemptions), and which disclosed or undisclosed inputs determine that answer", "criterion": "Compares the December 31, 2025 current portion (about 4,876 USD millions, the next-twelve-months recognition estimate) with FY2025 pool recognition of about 4,456 (4,237 travel + 219 non-travel, ±1). It must conclude that higher near-term recognition is indicated (by about 420) but that a net reversal of the pool is not determinable from the 10-K because 2026 miles earned are not disclosed. It must not rely on later-call or 2026 guidance figures as deferral evidence.", "fatal": true}, {"atom": "Defensible starting consideration population for mapping the Amex relative-selling-price allocation, chosen between (a) the dollar remuneration from American Express and (b) the cash-sales total from all loyalty marketing agreements, with both FY2025 reported dollar amounts and the reason the other measure is not the allocation base", "criterion": "Identifies total cash sales from marketing agreements (about $8.0 billion in FY2025, substantially all American Express) as the population the 10-K allocates by relative selling price. It must explain that the $8.2 billion remuneration from American Express is a differently defined measure that the 10-K does not reconcile to it, and that no post-10-K figure (for example the $9 billion 2026 call guidance) is used as FY2025 data. Billions as given in the 10-K are acceptable presentation.", "fatal": true}, {"atom": "For each allocated performance obligation (award travel; baggage fee waivers and other services performed in conjunction with a passenger's flight; lounge access; brand use and other remaining obligations; and priority boarding, whose receiving line is not separately disclosed): the receiving revenue line and recognition timing where disclosed, and whether the American Express-sourced portion of that line is identified, bounded, or not identifiable, with any computed bound", "criterion": "Maps:\n- award travel to loyalty program deferred revenue and then loyalty travel awards (passenger) on redemption/travel;\n- baggage fee waivers and other services in conjunction with a flight to travel-related services (passenger) when performed;\n- lounge access to miscellaneous (other revenue) as provided;\n- brand and other remaining obligations to loyalty program (other revenue) as miles are delivered. The American Express portions of award travel, baggage/flight services and lounge must be treated as not identifiable. The brand/remaining line must be given an upper bound of about 3,143 USD millions (±2) that still contains other partners. For priority boarding, stating that its receiving line and timing are not separately disclosed is preferred; a travel-related services placement explicitly labelled as an inference is acceptable; omitting a line assignment is not an error. In every case no identifiable American Express priority boarding amount may be given.", "fatal": true}, {"atom": "Whether balance-sheet current plus noncurrent loyalty program deferred revenue equals the Note 2 rollforward ending balance at December 31, 2025 and at December 31, 2024 (tie or no tie), with the summed amount at each date", "criterion": "Shows that balance-sheet current plus noncurrent loyalty program deferred revenue ties exactly to the Note 2 rollforward ending balances: 4,876 + 4,386 = 9,262 at December 31, 2025 and 4,314 + 4,512 = 8,826 at December 31, 2024 (USD millions).", "fatal": true}, {"atom": "Whether the cash-flow operating adjustment for loyalty program deferred revenue matches the Note 2 rollforward net change for each of 2025, 2024 and 2023, giving each year's rollforward net change, cash-flow amount and difference", "criterion": "Compares each year's rollforward net change with the cash-flow operating adjustment and states the differences in USD millions: 2025 436 vs 435 (1); 2024 406 vs 407 (1); 2023 538 vs 538 (0). It must conclude that they match within rounding (±1 on each figure).", "fatal": true}, {"atom": "Year-over-year change in the current and in the noncurrent loyalty program deferred revenue balances from December 31, 2024 to December 31, 2025, and the current share of the total pool at each date", "criterion": "Reports the current portion up about +562 USD millions (4,314 to 4,876, ±1) and the noncurrent portion down about 126 (4,512 to 4,386). The current share must be about 48.9% at December 31, 2024 and about 52.6% at December 31, 2025, computed as current divided by current plus noncurrent.", "fatal": true}], "evidence": [{"source_id": "S1", "quote": "In 2025, remuneration from American Express totaled $8.2 billion, which we expect to grow to $10 billion over the next few years.", "locator": "", "note": "Item 1 Business: FY2025 remuneration from American Express was $8.2 billion.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=In%202025%2C%20remuneration%20from%20American%20Express%20totaled%20%248.2%20billion%2C%20which,billion%20over%20the%20next%20few%20years", "link_method": "text", "n": 1}, {"source_id": "S1", "quote": "Remuneration from American Express related to the SkyMiles program were $8.2 billion during 2025, an increase of approximately 11% compared to 2024.", "locator": "", "note": "MD&A cash-flow discussion: remuneration from American Express related to the SkyMiles program was $8.2 billion in 2025.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Remuneration%20from%20American%20Express%20related%20to%20the%20SkyMiles%20program%20were,of%20approximately%2011%25%20compared%20to%202024", "link_method": "text", "n": 2}, {"source_id": "S1", "quote": "During the years ended December 31, 2025, 2024 and 2023, total cash sales from marketing agreements related to our loyalty program were $8.0 billion, $7.4 billion and $6.9 billion, respectively, which are allocated to travel and other performance obligations, as discussed below.", "locator": "", "note": "Critical accounting estimate: total cash sales from marketing agreements were $8.0 billion (2025), $7.4 billion (2024) and $6.9 billion (2023), and this population is allocated to travel and other performance obligations.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=During%20the%20years%20ended%20December%2031%2C%202025%2C%202024%20and%202023,other%20performance%20obligations%2C%20as%20discussed%20below", "link_method": "text", "n": 3}, {"source_id": "S1", "quote": "Delta Air Lines, Inc. | 2025 Form 10-K 64 Notes to the Consolidated Financial Statements Substantially all of our total cash sales from marketing agreements relate to our co-brand credit card relationship with American Express.", "locator": "", "note": "Note 2 of the 2025 Form 10-K consolidated financial statements: substantially all (not all) of total cash sales from marketing agreements relate to the American Express co-brand relationship.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Delta%20Air%20Lines%2C%20Inc.%20%7C%202025%20Form%2010%2DK,with", "link_method": "text", "n": 4}, {"source_id": "S1", "quote": "Cardholders earn miles for making purchases using co-branded cards, and certain cardholders may also receive baggage fee waivers, lounge access, priority boarding and other benefits while traveling on Delta.", "locator": "", "note": "Priority boarding is one of the benefits certain American Express cardholders may receive while traveling on Delta.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Cardholders%20earn%20miles%20for%20making%20purchases%20using%20co%2Dbranded%20cards%2C%20and,other%20benefits%20while%20traveling%20on%20Delta", "link_method": "text", "n": 5}, {"source_id": "S1", "quote": "We account for marketing agreements, including those with American Express, by allocating the consideration to the individual products and services delivered. We allocate the value based on the relative selling prices of those products and services, which generally consist of award travel, baggage fee waivers, lounge access, priority boarding and the use of our brand. We determine our best estimate of the selling prices by using a discounted cash flow analysis using multiple inputs and assumptions, including (1) the expected number of miles awarded and number of miles redeemed, (2) ETV for the award travel obligation adjusted for mileage breakage, (3) published rates on our website for baggage fees, lounge access and priority boarding while traveling on Delta, (4) brand value (using estimated royalties generated from the use of our brand) and (5) volume discounts provided to certain partners.", "locator": "", "note": "Marketing-agreement consideration, including American Express, is allocated by relative selling price to award travel, baggage fee waivers, lounge access, priority boarding and use of the brand; selling prices are estimated by discounted cash flow using the listed inputs. No allocation percentages are disclosed.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=We%20account%20for%20marketing%20agreements%2C%20including%20those%20with%20American%20Express,volume%20discounts%20provided%20to%20certain%20partners", "link_method": "text", "n": 6}, {"source_id": "S1", "quote": "We defer the amount allocated to award travel as part of loyalty program deferred revenue and recognize loyalty travel awards in passenger revenue as the miles are redeemed and transportation is provided.", "locator": "", "note": "Award travel is deferred in loyalty program deferred revenue and recognized as loyalty travel awards in passenger revenue as miles are redeemed and transportation is provided.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=We%20defer%20the%20amount%20allocated%20to%20award%20travel%20as%20part,are%20redeemed%20and%20transportation%20is%20provided", "link_method": "text", "n": 7}, {"source_id": "S1", "quote": "Revenue allocated to services performed in conjunction with a passenger's flight, such as baggage fee waivers, is recognized as travel-related services in passenger revenue when the related service is performed.", "locator": "", "note": "Revenue allocated to services performed in conjunction with a passenger's flight, with baggage fee waivers as the only named example, is recognized as travel-related services in passenger revenue when performed. Priority boarding is not named in this sentence.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Revenue%20allocated%20to%20services%20performed%20in%20conjunction%20with%20a,when%20the%20related%20service%20is%20performed", "link_method": "text", "n": 8}, {"source_id": "S1", "quote": "Revenue allocated to lounge access is recognized as miscellaneous in other revenue as access is provided.", "locator": "", "note": "Lounge access is recognized as miscellaneous in other revenue as access is provided.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Revenue%20allocated%20to%20lounge%20access%20is%20recognized%20as%20miscellaneous%20in,other%20revenue%20as%20access%20is%20provided", "link_method": "text", "n": 9}, {"source_id": "S1", "quote": "Revenue allocated to the remaining performance obligations, primarily brand value, is recorded as loyalty program in other revenue as miles are delivered.", "locator": "", "note": "Remaining performance obligations, primarily brand value, are recorded as loyalty program in other revenue as miles are delivered. The recognition mapping names no line for priority boarding.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Revenue%20allocated%20to%20the%20remaining%20performance%20obligations%2C%20primarily%20brand%20value,other%20revenue%20as%20miles%20are%20delivered", "link_method": "text", "n": 10}, {"source_id": "S1", "quote": "Miles are combined in one homogeneous pool and are not separately identifiable. Therefore, the revenue is comprised of miles that were part of the loyalty program deferred revenue balance at the beginning of the period as well as miles that were issued during the period.", "locator": "", "note": "SkyMiles miles form one homogeneous pool and are not separately identifiable; recognized revenue mixes opening-balance miles and miles issued during the period.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Miles%20are%20combined%20in%20one%20homogeneous%20pool%20and%20are%20not,that%20were%20issued%20during%20the%20period", "link_method": "text", "n": 11}, {"source_id": "S1", "quote": "The table below presents the activity of the current and noncurrent loyalty program deferred revenue, and includes miles earned through travel and miles sold to participating companies, which are primarily through marketing agreements.", "locator": "", "note": "The rollforward covers current and noncurrent loyalty program deferred revenue and includes both miles earned through travel and miles sold to participating companies.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=The%20table%20below%20presents%20the%20activity%20of%20the%20current%20and,which%20are%20primarily%20through%20marketing%20agreements", "link_method": "text", "n": 12}, {"source_id": "S1", "quote": "Loyalty program activity (in millions) 2025 2024 2023 Balance at January 1 $ 8,826 $ 8,420 $ 7,882 Miles earned 4,892 4,463 4,173 Travel miles redeemed ( 4,237 ) ( 3,841 ) ( 3,462 ) Non-travel miles redeemed ( 219 ) ( 216 ) ( 173 ) Balance at December 31 $ 9,262 $ 8,826 $ 8,420", "locator": "", "note": "Rollforward ($ millions) for 2025, 2024, 2023: Balance at January 1 8,826 / 8,420 / 7,882; Miles earned 4,892 / 4,463 / 4,173; Travel miles redeemed (4,237) / (3,841) / (3,462); Non-travel miles redeemed (219) / (216) / (173); Balance at December 31 9,262 / 8,826 / 8,420.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Loyalty%20program%20activity,8%2C420", "link_method": "text", "n": 13}, {"source_id": "S1", "quote": "The timing of mile redemptions can vary widely; however, the majority of new miles have historically been redeemed within two years of being earned. The loyalty program deferred revenue classified as a current liability represents our estimate of revenue expected to be recognized in the next twelve months based on projected redemptions, while the balance classified as a noncurrent liability represents our estimate of revenue expected to be recognized beyond twelve months.", "locator": "", "note": "Most new miles have historically been redeemed within two years; the current portion is the estimate of revenue expected to be recognized in the next twelve months based on projected redemptions, the noncurrent portion beyond twelve months.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=The%20timing%20of%20mile%20redemptions%20can%20vary%20widely%3B%20however%2C%20the,to%20be%20recognized%20beyond%20twelve%20months", "link_method": "text", "n": 14}, {"source_id": "S1", "quote": "Year Ended December 31, (in millions) 2025 2024 2023 Refinery $ 5,077 $ 4,642 $ 3,379 Loyalty program 3,362 3,297 3,093 Ancillary businesses 937 772 840 Miscellaneous 1,320 1,216 1,104 Total other revenue $ 10,696 $ 9,927 $ 8,416", "locator": "", "note": "Other revenue ($ millions) 2025 / 2024 / 2023: Loyalty program 3,362 / 3,297 / 3,093; Miscellaneous 1,320 / 1,216 / 1,104.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Year%20Ended%20December%2031", "link_method": "text", "n": 15}, {"source_id": "S1", "quote": "Loyalty Program. This relates to revenues from brand usage by third parties and other performance obligations embedded in miles sold, which are included within the total cash sales from marketing agreements, discussed above. This also includes the redemption of miles for non-travel awards.", "locator": "", "note": "Loyalty program other revenue holds brand usage and other performance obligations embedded in miles sold, plus non-travel award redemptions.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Loyalty%20Program.%20This%20relates%20to%20revenues%20from%20brand%20usage%20by,awards", "link_method": "text", "n": 16}, {"source_id": "S1", "quote": "Miscellaneous. This is primarily composed of revenues related to lounge access, including access provided to certain American Express cardholders, travel products (e.g., car rentals or hotels booked with our commercial partners), codeshare agreements and international joint venture partnership contractual settlements.", "locator": "", "note": "Miscellaneous other revenue includes lounge access (including for certain American Express cardholders), travel products, codeshare agreements and international joint venture partnership contractual settlements.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Miscellaneous.%20This%20is%20primarily%20composed%20of%20revenues%20related%20to%20lounge,international%20joint%20venture%20partnership%20contractual%20settlements", "link_method": "text", "n": 17}, {"source_id": "S1", "quote": "Ticket - Premium products 22,097 20,599 1,498 7 % Loyalty travel awards 4,237 3,841 396 10 % Travel-related services 2,043 1,957 86 4 % Total passenger revenue $ 51,768 $ 50,894 $ 874 2 %", "locator": "", "note": "Passenger revenue ($ millions) 2025 / 2024: Loyalty travel awards 4,237 / 3,841; Travel-related services 2,043 / 1,957.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Ticket%20%2D%20Premium%20products,874", "link_method": "text", "n": 18}, {"source_id": "S1", "quote": "Loyalty program deferred revenue 4,876 4,314 Fuel card obligation 1,100 1,100 Other accrued liabilities 1,945 1,812 Total current liabilities 27,624 26,670 Noncurrent Liabilities: Debt and finance leases 12,507 14,019 Noncurrent operating leases 5,353 5,814 Pension, postretirement and related benefits 3,156 3,144 Loyalty program deferred revenue 4,386 4,512", "locator": "", "note": "Balance sheet ($ millions): current loyalty program deferred revenue 4,876 and 4,314; noncurrent loyalty program deferred revenue 4,386 and 4,512.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Loyalty%20program%20deferred%20revenue,Loyalty%20program%20deferred%20revenue", "link_method": "text", "n": 19}, {"source_id": "S1", "quote": "Air traffic liability 63 50 ( 1,216 ) Loyalty program deferred revenue 435 407 538 Profit sharing", "locator": "", "note": "Cash-flow operating adjustment for loyalty program deferred revenue ($ millions): 435, 407, 538.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=Air%20traffic%20liability", "link_method": "text", "n": 20}, {"source_id": "S1", "quote": "At December 31, 2025, the aggregate deferred revenue balance associated with the SkyMiles program was $9.3 billion.", "locator": "", "note": "The critical accounting estimate states a rounded $9.3 billion SkyMiles deferred revenue balance at December 31, 2025.", "link": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm#:~:text=At%20December%2031%2C%202025%2C%20the%20aggregate%20deferred%20revenue%20balance%20associated,the%20SkyMiles%20program%20was%20%249.3%20billion", "link_method": "text", "n": 21}, {"source_id": "S2", "quote": "With continued momentum in both new card acquisitions and spend, we expect remuneration of $9 billion this year, up 10% over 2025.", "locator": "Page 4", "note": "On the Q2 2026 call Delta said it expects American Express remuneration of $9 billion in 2026; this is forward guidance, not a FY2025 figure.", "link": "https://s2.q4cdn.com/181345880/files/doc_events/2026/July/CORRECTED-TRANSCRIPT_-Delta-Air-Lines-Inc-DAL-US-Q2-2026-Earnings-Call-10-July-2026-10_00-AM-ET.pdf#page=4", "link_method": "page", "n": 22}, {"source_id": "S2", "quote": "Delta Air Lines, Inc. (DAL) Corrected Transcript Q2 2026 Earnings Call 10-Jul-2026", "locator": "Page 2", "note": "The remuneration remark comes from Delta Air Lines (DAL) Q2 2026 earnings call of 10-Jul-2026.", "link": "https://s2.q4cdn.com/181345880/files/doc_events/2026/July/CORRECTED-TRANSCRIPT_-Delta-Air-Lines-Inc-DAL-US-Q2-2026-Earnings-Call-10-July-2026-10_00-AM-ET.pdf#page=2", "link_method": "page", "n": 23}], "sources": [{"id": "S1", "title": "Delta Air Lines — Form 10-K, fiscal year ended December 31, 2025", "url": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/dal-20251231.htm", "index_url": "https://www.sec.gov/Archives/edgar/data/27904/000002790426000013/0000027904-26-000013-index.html", "doc_type": "10-K", "date": "2026-02-11"}, {"id": "S2", "title": "Delta Air Lines — Q2 2026 earnings call transcript (corrected)", "url": "https://s2.q4cdn.com/181345880/files/doc_events/2026/July/CORRECTED-TRANSCRIPT_-Delta-Air-Lines-Inc-DAL-US-Q2-2026-Earnings-Call-10-July-2026-10_00-AM-ET.pdf", "index_url": "", "publisher": "Delta Air Lines Inc.", "doc_type": "earnings_call_transcript", "date": "2026-07-10"}], "has_trajectories": true, "reference_note": null, "frozen_sha256": "23dbf9e50dc3b2a33a9a6542f0ccb30c91a7caa7cdd952fdb183084c7207d0b5", "review_scope": "The question, reference analysis and scoring criteria used for this evaluation.", "lineage": {"stages": [{"key": "discovery", "label": "Discovery", "status": "passed", "note": "1 documented step.", "events": [{"date": "2026-10-03T12:57:19.467427Z", "title": "Task proposed from a verified source relationship", "detail": "The proposal identified 7 candidate relationships from 1 source.", "kind": "ok"}]}, {"key": "novelty_check", "label": "Novelty check", "status": "passed", "note": "1 documented step.", "events": [{"date": "2026-10-03T12:57:19.467427Z", "title": "Compared with existing and proposed tasks", "detail": "The candidate was compared with existing and proposed tasks and continued to the next stage.", "kind": "ok"}]}, {"key": "integration", "label": "Integration", "status": "passed", "note": "3 documented steps.", "events": [{"date": "2026-10-03T12:57:19.467427Z", "title": "183 statements classified as reported fact or inference", "detail": "", "kind": "ok"}, {"date": "2026-10-03T12:57:19.467427Z", "title": "Supporting passages located in 2 sources", "detail": "The supporting passages were located in the source documents.", "kind": "ok"}, {"date": "2026-10-03T12:57:19.467427Z", "title": "Analysis linked: 8 relationships, 8 answer components, 36 supporting passages", "detail": "Using only Delta's FY2025 Form 10-K, map the American Express co-brand consideration through the disclosed relative-selling-price allocation onto the revenue lines that receive each performance obligation and onto the SkyMiles deferred revenue pool. Choose the defensible consideration population, reconcile the deferred pool across the balance sheet, the Note 2 rollforward and the cash-flow statement, and state at what population level any direction for the gap between deferral and recognition holds, and what the current/noncurrent split implies for the near term.", "kind": "ok"}]}, {"key": "difficulty", "label": "Difficulty screen", "status": "returned", "note": "Revised once after comparison with other proposed tasks, then reassessed and selected.", "events": [{"date": null, "title": "Initial difficulty assessment", "kind": "ok", "detail": "Estimated difficulty: highest band. Reasoning depth: 4/4; Reconciliation across sources: 3/4; Entity and population definitions: 4/4; Periods and document versions: 3/4; Conditional reasoning: 3/4; Professional judgment: 4/4; Changes in financial or regulatory state: 3/4; Verification of resulting outcomes: 3/4."}, {"date": null, "title": "Selected for revision after comparison with other proposed tasks", "kind": "edit", "detail": "The task was revised to add a further analysis supported by the sources, then assessed again."}, {"date": null, "title": "Reconcile the loyalty rollforward, balance sheet and cash flow", "kind": "edit", "detail": "Added a reconciliation of the SkyMiles activity rollforward with current and noncurrent deferred-revenue balances and the operating cash-flow adjustment. These checks connect the reported net deferral to the balance’s expected recognition timing, while keeping conclusions at the level of pooled flight-earned and partner-sold miles rather than attributing them to American Express."}, {"date": null, "title": "Reassessment of the revised version", "detail": "Estimated difficulty: highest band. Reasoning depth: 4/4; Reconciliation across sources: 4/4; Entity and population definitions: 4/4; Periods and document versions: 4/4; Conditional reasoning: 4/4; Professional judgment: 4/4; Changes in financial or regulatory state: 4/4; Verification of resulting outcomes: 4/4.", "kind": "ok"}, {"date": null, "title": "Assessment rationale (excerpt)", "detail": "This task requires a deep, multi-stage map from co-brand consideration through several performance obligations, recognition lines, and a pooled deferred-revenue balance. It requires reconciling disclosures across the 10-K narrative, Note 2 rollforward, balance-sheet current/noncurrent presentation, cash-flow adjustment, and revenue-line descriptions, including rounding and population compatibility.", "kind": "ok"}, {"date": null, "title": "Selected after reassessment", "detail": "This version was selected for evidence collection and reference-answer development.", "kind": "ok"}], "assessment": {"mode": "structural_estimate_without_solving", "predicted_band": "frontier", "dimensions": {"relation_depth": 4, "cross_source_reconciliation": 4, "identity_or_population": 4, "temporal_or_version": 4, "conditional_branching": 4, "professional_judgment": 4, "state_transition": 4, "post_action_verification": 4}, "shortcut_available": false, "material_ambiguity": false, "batch_rank": 1, "cohort_size": 13, "decision": "selected", "previous_versions": [{"predicted_band": "frontier", "dimensions": {"relation_depth": 4, "cross_source_reconciliation": 3, "identity_or_population": 4, "temporal_or_version": 3, "conditional_branching": 3, "professional_judgment": 4, "state_transition": 3, "post_action_verification": 3}, "batch_rank": 9, "cohort_size": 18, "decision": "revision_required", "change_title": "Reconcile the loyalty rollforward, balance sheet and cash flow", "change_summary": "Added a reconciliation of the SkyMiles activity rollforward with current and noncurrent deferred-revenue balances and the operating cash-flow adjustment. These checks connect the reported net deferral to the balance’s expected recognition timing, while keeping conclusions at the level of pooled flight-earned and partner-sold miles rather than attributing them to American Express."}]}}, {"key": "evidence", "label": "Reference analysis", "status": "passed", "note": "16 documented steps.", "events": [{"date": "2026-10-03T13:30:08.084795Z", "title": "Reference calculation recorded in 22 steps", "detail": "", "kind": "ok"}, {"date": "2026-10-03T13:30:08.084795Z", "title": "Analysis objective defined", "detail": "Using only Delta's FY2025 Form 10-K, map the American Express co-brand consideration through the disclosed relative-selling-price allocation onto the revenue lines that receive each performance obligation and onto the SkyMiles deferred revenue pool. Choose the defensible consideration population, reconcile the deferred pool across the balance sheet, the Note 2 rollforward and the cash-flow statement, and state at what population level any direction for the gap between deferral and recognition holds, and what the current/noncurrent split implies for the near term.", "kind": "ok"}, {"date": "2026-10-03T13:30:08.084795Z", "title": "Reference analysis written", "detail": "In Delta's FY2025 10-K, the relative-selling-price allocation applies to total cash sales from marketing agreements ($8.0 billion, substantially all American Express), not to the $8.2 billion of remuneration from American Express. Of the allocated obligations only the brand/remaining-obligations line can be bounded (about $3,143M ceiling within loyalty program revenue); award travel, baggage fee waivers and lounge access cannot be isolated in their receiving lines. The SkyMiles deferred pool ties exactly across the balance sheet and Note 2 (9,262 and 8,826) and the cash-flow adjustment matches the rollforward within $1M for 2023-2025, showing a net deferral build each year (436, 406, 538). The current portion rose $562M to 52.6% of the pool and exceeds FY2025 pool recognition (4,456), indicating higher near-term recognition, but a net reversal is not determinable without 2026 miles earned, and the direction holds only at pool level, not for American Express specifically.", "kind": "ok"}, {"date": "2026-10-03T13:30:08.084795Z", "title": "Evidence assembled: 22 verbatim quotations", "detail": "", "kind": "ok"}, {"date": "2026-10-03T13:30:08.084795Z", "title": "Definitions and scope checked: supported", "detail": "Compatible on entity, period, unit, scope, population.", "kind": "ok"}, {"date": "2026-10-03T13:30:08.084795Z", "title": "Professional interpretation checked: supported", "detail": "", "kind": "ok"}, {"date": "2026-10-03T16:08:59.049914Z", "title": "Quoted passages checked against sources", "detail": "", "kind": "ok"}, {"date": "2026-10-03T16:08:59.189706Z", "title": "Evidence review completed", "detail": "", "kind": "ok"}, {"date": "2026-10-03T21:21:54.901581Z", "title": "Reference calculation recorded in 23 steps", "detail": "", "kind": "ok"}, {"date": "2026-10-03T21:21:54.901581Z", "title": "Analysis objective defined", "detail": "Using only Delta's FY2025 Form 10-K, map the American Express co-brand consideration through the disclosed relative-selling-price allocation onto the revenue lines that receive each performance obligation and onto the SkyMiles deferred revenue pool. Choose the defensible consideration population, reconcile the deferred pool across the balance sheet, the Note 2 rollforward and the cash-flow statement, and state at what population level any direction for the gap between deferral and recognition holds, and what the current/noncurrent split implies for the near term.", "kind": "ok"}, {"date": "2026-10-03T21:21:54.901581Z", "title": "Reference analysis written", "detail": "In Delta's FY2025 10-K, the relative-selling-price allocation applies to total cash sales from marketing agreements ($8.0 billion, substantially all American Express), not to the $8.2 billion of remuneration from American Express. Of the allocated obligations only the brand/remaining-obligations line can be bounded (about $3,143M ceiling within loyalty program revenue); award travel, baggage fee waivers and lounge access cannot be isolated in their receiving lines, and priority boarding's receiving line and timing are not separately disclosed (travel-related services only as a labelled inference) with no identifiable American Express amount. The SkyMiles deferred pool ties exactly across the balance sheet and Note 2 (9,262 and 8,826) and the cash-flow adjustment matches the rollforward within $1M for 2023-2025, showing a net deferral build each year (436, 406, 538). The current portion rose $562M to 52.6% of the pool and exceeds FY2025 pool recognition (4,456), indicating higher near-term recognition, but a net reversal is not determinable without 2026 miles earned, and the direction holds only at pool level, not for American Express specifically.", "kind": "ok"}, {"date": "2026-10-03T21:21:54.901581Z", "title": "Evidence assembled: 23 verbatim quotations", "detail": "", "kind": "ok"}, {"date": "2026-10-03T21:21:54.901581Z", "title": "Definitions and scope checked: supported", "detail": "Compatible on entity, period, unit, scope, population.", "kind": "ok"}, {"date": "2026-10-03T21:21:54.901581Z", "title": "Professional interpretation checked: supported", "detail": "", "kind": "ok"}, {"date": "2026-10-04T03:14:05.577601Z", "title": "Quoted passages checked against sources", "detail": "", "kind": "ok"}, {"date": "2026-10-04T03:14:05.724756Z", "title": "Evidence review completed", "detail": "", "kind": "ok"}]}, {"key": "reproduction", "label": "Independent reproduction", "status": "passed", "note": "4 documented steps.", "events": [{"date": "2026-10-03T16:34:13.955314Z", "title": "Independent-review materials checked", "detail": "The independent reviewer received the objective, supporting quotations and descriptions of the required outputs, without the reference answer.", "kind": "ok"}, {"date": "2026-10-03T16:34:14.010787Z", "title": "Independent reproduction: reproduced (8 answer components)", "detail": "", "kind": "ok"}, {"date": "2026-10-04T03:23:10.795461Z", "title": "Independent-review materials checked", "detail": "The independent reviewer received the objective, supporting quotations and descriptions of the required outputs, without the reference answer.", "kind": "ok"}, {"date": "2026-10-04T03:23:10.851553Z", "title": "Independent reproduction: reproduced (8 answer components)", "detail": "", "kind": "ok"}]}, {"key": "comparison", "label": "Comparison", "status": "passed", "note": "3 documented steps.", "events": [{"date": "2026-10-03T17:18:29.634969Z", "title": "Answer-by-answer comparison: equivalent", "detail": "All eight reference-answer components were reproduced. The balance-sheet reconciliation matched exactly; the other seven show only nonmaterial wording, representation, entailed surplus or omitted supplementary detail, each accepted as equivalent after checking the cited source passages. All scored numbers (3,143; 9,262/8,826; 436/406/538 vs 435/407/538; 562; 420) recompute exactly. The independent source check found no shared error.", "kind": "ok"}, {"date": "2026-10-03T17:18:29.634969Z", "title": "Source check: shared assumptions supported", "detail": "The reviewer reopened the cited source passages and recomputed every decisive figure and boundary independently of the two answers. No shared error or unresolved premise was found.", "kind": "ok"}, {"date": "2026-10-04T04:01:55.517660Z", "title": "Answer-by-answer comparison: equivalent", "detail": "All 8 reference answer components were reproduced with the same conclusions and figures: cash sales $8.0B as the allocation base; the $3,143M brand ceiling; balance-sheet ties of 9,262 and 8,826; cash-flow differences of 1/1/0; net builds of 436/406/538; current portion +562; net reversal not determinable; pool level only, not attributable to American Express. The observed differences are wording, precision or detail supported by the evidence, and each is covered by an accepted alternative or by the cited source passages. No decisive or unresolved conflict remains.", "kind": "ok"}]}, {"key": "family", "label": "Problem family", "status": "passed", "note": "2 documented steps.", "events": [{"date": "2026-10-03T17:28:55.737338Z", "title": "Problem family accepted", "detail": "The verified analysis was accepted within the proposed task type.", "kind": "ok"}, {"date": "2026-10-04T04:03:14.589305Z", "title": "Problem family accepted", "detail": "The verified analysis was accepted within the proposed task type.", "kind": "ok"}]}, {"key": "question", "label": "Question & scoring criteria", "status": "passed", "note": "17 documented steps.", "events": [{"date": "2026-10-03T18:47:58.732071Z", "title": "Scoring criteria checked: 8 scored items, 8 automatic-failure rules", "detail": "", "kind": "ok"}, {"date": "2026-10-03T18:47:58.732091Z", "title": "Question and scoring criteria prepared", "detail": "The task asks whether Delta's FY2025 10-K supports the claim that American Express consideration is deferring faster than it is recognized and will reverse soon. The verified answer splits that claim. The net deferral build holds only for the pooled SkyMiles population, not for American Express specifically. The near-term test points to higher recognition, but a net reversal cannot be determined without 2026 miles earned. The supporting components (consideration base, obligation-to-line map with identifiability, three-statement tie-out, current/noncurrent shift) are required only because the judgment depends on them. The question states the conventions an analyst could choose differently (net-change sign and horizon, pool definition and share denominator, near-term comparison basis, bound-not-estimate treatment, units and precision) without revealing values.", "kind": "ok"}, {"date": "2026-10-03T18:49:06.307373Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T18:54:30.454071Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:02:00.461285Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:18:02.539380Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:28:39.261652Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:34:36.080504Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:39:02.020966Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:48:43.091366Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-03T19:49:28.532771Z", "title": "Question finalized for evaluation", "detail": "", "kind": "ok"}, {"date": "2026-10-04T05:12:14.283463Z", "title": "Scoring criteria checked: 8 scored items, 8 automatic-failure rules", "detail": "", "kind": "ok"}, {"date": "2026-10-04T05:12:14.283484Z", "title": "Question and scoring criteria prepared", "detail": "There is one decisive judgment: whether Delta's FY2025 10-K supports the claim that American Express consideration is deferring faster than it is recognized and will reverse soon. The verified answer splits that claim. The net deferral build holds only for the pooled SkyMiles population, not for American Express specifically. The near-term test indicates higher recognition, but a net reversal cannot be determined without 2026 miles earned. The supporting components (consideration base, obligation-to-line map with identifiability, three-statement tie-out, current/noncurrent shift) are required only because the judgment depends on them. Repair change: the line-mapping clause now asks the answer to say where the 10-K does not disclose a receiving line or timing and to label inferred placements as inferences. This makes 'priority boarding not separately disclosed' the preferred answer, accepts a labelled travel-related services inference, and allows the answer to leave priority boarding unassigned. The question states every convention a competent analyst could choose differently (net-change sign and horizon, pool definition and share denominator, near-term comparison basis, bound-not-estimate treatment, units and precision) without revealing values. Everything else is unchanged from the previous question.", "kind": "ok"}, {"date": "2026-10-04T05:13:02.400529Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-04T05:13:55.066845Z", "title": "Question finalized for evaluation", "detail": "", "kind": "ok"}, {"date": "2026-10-04T06:48:12.441110Z", "title": "Duplicate check: no duplicate identified", "detail": "Compared against existing tasks; no duplicate was identified.", "kind": "ok"}, {"date": "2026-10-04T06:48:55.644411Z", "title": "Question finalized for evaluation", "detail": "", "kind": "ok"}]}, {"key": "validity", "label": "Validity review", "status": "passed", "note": "1 documented step.", "events": [{"date": "2026-10-04T06:33:45.355793Z", "title": "Validity review: valid", "detail": "", "kind": "ok"}]}, {"key": "consistency", "label": "Consistency review", "status": "returned", "note": "1 issue identified during review.", "events": [{"date": "2026-10-03T20:19:46.212930Z", "title": "Defect found: reference analysis or reasoning", "detail": "The reference answer was returned for correction.", "kind": "issue"}, {"date": "2026-10-04T06:41:23.450229Z", "title": "Question–reference consistency: consistent", "detail": "", "kind": "ok"}, {"date": "2026-10-04T06:41:24.154881Z", "title": "Review decision: passed", "detail": "", "kind": "ok"}, {"date": "2026-10-04T06:49:19.330443Z", "title": "Review decision: passed", "detail": "", "kind": "ok"}]}, {"key": "polish", "label": "Polish", "status": "edited", "note": "1 wording revision.", "events": [{"date": "2026-10-04T06:47:38.449558Z", "title": "Polish review 1: revision requested", "detail": "", "kind": "edit"}, {"date": "2026-10-04T06:51:26.588911Z", "title": "Polish review 2: passed", "detail": "", "kind": "ok"}]}, {"key": "acceptance", "label": "Acceptance", "status": "passed", "note": "Accepted.", "events": []}]}};
